import{_ as a,o as l,c as o,a3 as r}from"./chunks/framework.BTt0kA_k.js";const u=JSON.parse('{"title":"RelayPulse 3.0.2 发布说明","description":"","frontmatter":{},"headers":[],"relativePath":"user/releases/v3.0.2.md","filePath":"user/releases/v3.0.2.md"}'),i={name:"user/releases/v3.0.2.md"};function t(s,e,d,c,n,h){return l(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="relaypulse-3-0-2-发布说明" tabindex="-1">RelayPulse 3.0.2 发布说明 <a class="header-anchor" href="#relaypulse-3-0-2-发布说明" aria-label="Permalink to &quot;RelayPulse 3.0.2 发布说明&quot;">​</a></h1><p>发布日期：2026 年 11 月 13 日</p><p>3.0.2 更新站点探针策略、IQ 测试请求配置和请求记录，让界面预览、实际请求及落盘快照更一致。</p><h2 id="新增与调整" tabindex="-1">新增与调整 <a class="header-anchor" href="#新增与调整" aria-label="Permalink to &quot;新增与调整&quot;">​</a></h2><ul><li>站点默认策略和模型策略使用一致的请求头、请求体编辑器，支持字段启停、JSON 粘贴和请求预览。</li><li>模型请求策略分为继承站点默认、独立策略和自定义策略。自定义探针端点可单独配置；关闭时保留站点默认端点。</li><li>新建站点时，标准协议会预填可编辑的模型列表及探测端点；自定义 HTTP 的端点留空。创建站点时默认不显示在小面板中。</li><li>模型发现失败时仍保存站点，支持之后修改模型列表端点、重试同步或手动添加模型。模型目录分页继续使用上游游标。</li><li>IQ 测试参与者可以独立配置请求头和请求体，并保存自己的配置快照。推理档位统一为 <code>low</code>、<code>medium</code>、<code>high</code>、<code>xhigh</code>、<code>max</code> 和“自定义”。自定义 HTTP 的档位仅作为标记，Body 由用户填写。</li><li>探针和 IQ 请求预览、请求快照及 JSONL 记录统一展示实际请求地址，并对访问凭据脱敏。</li><li>改进流式响应内容解析和请求记录，区分输出内容、响应字节数与服务商返回的 Token 用量。</li></ul><h2 id="地址填写提醒" tabindex="-1">地址填写提醒 <a class="header-anchor" href="#地址填写提醒" aria-label="Permalink to &quot;地址填写提醒&quot;">​</a></h2><p>模型发现、探针和 IQ 请求地址按 <code>Base URL + 端点</code> 原文拼接。程序不会补版本路径或斜杠，也不会纠正输入。添加或编辑站点后，请检查地址预览并按服务商文档填写完整路径。</p><h2 id="兼容与验证" tabindex="-1">兼容与验证 <a class="header-anchor" href="#兼容与验证" aria-label="Permalink to &quot;兼容与验证&quot;">​</a></h2><p>服务商是否接受某个请求字段或推理档位，由服务商和模型决定。需要额外请求头或请求体字段时，请自行在对应策略中填写，并通过请求预览与预检验证。</p><p>阅读<a href="./../">使用者手册</a>查看站点、探针、IQ 测试和请求记录的操作说明；开发者可阅读<a href="./../../developer/">开发者文档</a>。</p>',10)])])}const _=a(i,[["render",t]]);export{u as __pageData,_ as default};
